export const SENT = [{"at": 0, "end": 176, "text": "In this town of just 1,903 people, a retired couple found a way to beat the lottery."}, {"at": 186, "end": 199, "text": "Legally."}, {"at": 211, "end": 248, "text": "For 9 years."}, {"at": 266, "end": 460, "text": "In 2003, retired store owner Jerry Selbee read a brochure for a new Michigan game, Winfall."}, {"at": 464, "end": 532, "text": "He found the loophole in 3 minutes."}, {"at": 535, "end": 689, "text": "When the jackpot hit $5 million and nobody won, the money rolled down to the smaller prizes."}, {"at": 696, "end": 786, "text": "On those days, enough tickets put the math on your side."}, {"at": 792, "end": 815, "text": "Jerry tried it."}, {"at": 824, "end": 884, "text": "$3,600 in."}, {"at": 887, "end": 934, "text": "$6,300 back."}, {"at": 937, "end": 1133, "text": "He and his wife Marge formed a company with family and friends, and played 12 roll-downs, until Michigan ended the game."}, {"at": 1139, "end": 1211, "text": "Then they found a similar game in Massachusetts."}, {"at": 1214, "end": 1401, "text": "For 6 years, they drove 900 miles a trip, often betting over $600,000."}, {"at": 1407, "end": 1433, "text": "They weren't alone."}, {"at": 1436, "end": 1519, "text": "A group started by MIT students played it too."}, {"at": 1522, "end": 1666, "text": "In 2011, the Boston Globe broke the story, and many suspected a rigged game."}, {"at": 1671, "end": 1710, "text": "The state investigated."}, {"at": 1714, "end": 1793, "text": "The betting was legal, and no one's odds were hurt."}, {"at": 1799, "end": 1905, "text": "The state itself made $120 million from it."}, {"at": 1911, "end": 2108, "text": "In all, their company won over $26 million, nearly $8 million of it profit before tax."}, {"at": 2113, "end": 2150, "text": "Theirs went to family."}, {"at": 2156, "end": 2217, "text": "Sometimes the edge isn't luck."}, {"at": 2220, "end": 2265, "text": "It's reading the rules."}];
